/**
 * REAL data for the diagnostic walk — extracted from the live cities tool's
 * public parquet files (cities.taimur.sh/data/*.parquet) by
 * scripts/build-real-data.mjs. Not synthesized: these are the same numbers the
 * live profile pages draw.
 *
 *   metros   city_panel.parquet (population, avg_wage) + city_housing.parquet
 *            (ZHVI, tier "all"), USA only
 *   places   place_panel.parquet (population, avg_wage) + place_housing.parquet
 *            (ZHVI, tier "all") for EVERY US place ≥ 100k population with
 *            population + wage readings at the window and a resolvable MSA
 *            (place_directory msa_id → the metro table) — the FIELD the
 *            explainer pages sort; each row carries its MSA's pop CAGR so the
 *            demand sub-fork reads the city's real metro, not the dot itself.
 *            A place with no home series of its own reads its metro's
 *            (the live tool's fallback; 0 of the current field use it)
 *   cities   the four walkable sample places, joined to their MSA
 *   window   PINNED 2017 → 2022, endpoints SNAPPED per series
 *
 * THE WINDOW IS PINNED ON PURPOSE, AND ENDPOINTS SNAP. Pay broadly ends in
 * 2022 while population and home values run later, so the target window is
 * pinned for every series and every median. Within it, each series' endpoint
 * snaps to the nearest year that has data (the live tool's cagrPair rule,
 * CAGR over the actual span) — Connecticut's wage series ends in 2020, and
 * requiring the pinned endpoints outright drops all 4 CT metros + 5 cities.
 *
 * VALUES ARE FULL PRECISION — never round them before classifying. The pop
 * median is ≈0.4998 %/yr: stored at 2 decimals it becomes 0.50 and every
 * knife-edge city (Mesa, Augusta, Albany, Richardson TX) flips a fork.
 * Round for display only.
 *
 * Regenerate: node scripts/build-real-data.mjs
 */

export const DATA_WINDOW = { from: 2017, to: 2022 } as const;

/** The SUPPLY GATE: median home-value CAGR (%/yr) across ALL US places with
 *  a ZHVI series (n = 15758) — the live tool's classifySupply
 *  benchmark at place grain. NOT the metro median (≈8.86, which misroutes
 *  El Cajon, Miami and Orange CA), and NOT the ≥100k field's own median. */
export const PLACE_HOME_MED = 8.644445648340394;
/** How many US places that gate median is computed across. */
export const PLACE_HOME_N = 15758;

export interface RealMetro {
  id: string;
  name: string;
  /** population growth, CAGR %/yr */
  pop: number;
  /** average-wage growth, CAGR %/yr */
  wage: number;
  /** home-value growth (ZHVI), CAGR %/yr — null where Zillow has no series */
  home: number | null;
  /** population level nearest 2022, for dot area */
  size: number;
}

